/**
 * YunoBot Neural Engine — custom in-browser neural network runtime.
 *
 * Pure JS, zero dependencies, zero network requests. Loads int8-quantized
 * weights (window.YUNOBOT_NN_WEIGHTS, generated by dev/yunobot-nn/train.mjs)
 * and runs a fastText-style supervised embedding network:
 *
 *   tokens -> vocab rows + char-trigram/bigram hash rows -> mean vector h
 *   1) softmax head (W·h + b)         -> intent probability (open-set safe
 *      thanks to a trained out-of-scope class)
 *   2) cosine(h_norm, intent centroid) -> agreement boost for paraphrases
 *
 * Inference is a handful of float ops (<1 ms typical) so it runs on the
 * main thread without a worker and answers instantly on any device.
 *
 * Exposes: window.YunoBotNN.ready, window.YunoBotNN.match(text, topN)
 */
(function () {
    'use strict';

    var weights = window.YUNOBOT_NN_WEIGHTS;
    var api = { ready: false, match: function () { return []; } };
    window.YunoBotNN = api;
    if (!weights || !weights.vocab) return;

    // ============================================================
    // Decode base64 -> typed arrays and dequantize to Float32
    // ============================================================
    function b64ToBytes(b64) {
        var bin = atob(b64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return bytes;
    }

    function dequantize(b64q, b64s) {
        var q = new Int8Array(b64ToBytes(b64q).buffer);
        var s = new Float32Array(b64ToBytes(b64s).buffer);
        var out = new Float32Array(q.length);
        for (var i = 0; i < q.length; i++) out[i] = q[i] * s[(i / weights.dim) | 0];
        return out;
    }

    function decodeF32(b64) {
        return new Float32Array(b64ToBytes(b64).buffer);
    }

    var DIM = weights.dim;
    var NUM_BUCKETS = weights.buckets;
    var WORD_WEIGHT = weights.wordWeight || 1;
    var Ev, Eb, W, B, C;
    var vocabIndex = new Map();
    try {
        Ev = dequantize(weights.evQ, weights.evS);
        Eb = dequantize(weights.ebQ, weights.ebS);
        C = decodeF32(weights.cF);
        W = decodeF32(weights.wF);
        B = decodeF32(weights.bW);
        for (var i = 0; i < weights.vocab.length; i++) vocabIndex.set(weights.vocab[i], i);
    } catch (e) {
        if (window.console) console.warn('[YunoBotNN] weight decode failed:', e);
        return;
    }
    var INTENTS = weights.intents;
    var N_INTENTS = INTENTS.length;

    // ============================================================
    // Tokenizer + features (identical to dev/yunobot-nn/train.mjs)
    // ============================================================
    function tokenize(text) {
        return text
            .toLowerCase()
            .replace(/[^\p{L}\p{N}+#\s]/gu, ' ')
            .split(/\s+/)
            .filter(Boolean);
    }

    function charTrigrams(word) {
        var w = '<' + word + '>';
        var grams = [];
        for (var i = 0; i <= w.length - 3; i++) grams.push(w.slice(i, i + 3));
        return grams;
    }

    function hash32(str) {
        var h = 0x811c9dc5;
        for (var i = 0; i < str.length; i++) {
            h ^= str.charCodeAt(i);
            h = Math.imul(h, 0x01000193);
        }
        return h >>> 0;
    }

    // ============================================================
    // Embed: mean of feature rows -> raw h (softmax) + normalized (cosine)
    // ============================================================
    var hRaw = new Float32Array(DIM);
    var hNorm = new Float32Array(DIM);

    function embed(text) {
        var toks = tokenize(text);
        hRaw.fill(0);
        var n = 0;
        for (var i = 0; i < toks.length; i++) {
            var t = toks[i];
            var id = vocabIndex.get(t);
            if (id !== undefined) {
                var base = id * DIM;
                for (var d = 0; d < DIM; d++) hRaw[d] += Ev[base + d] * WORD_WEIGHT;
                n += WORD_WEIGHT;
            }
            var grams = charTrigrams(t);
            for (var g = 0; g < grams.length; g++) {
                var bbase = (hash32('t' + grams[g]) % NUM_BUCKETS) * DIM;
                for (var d2 = 0; d2 < DIM; d2++) hRaw[d2] += Eb[bbase + d2];
                n++;
            }
            if (i > 0) {
                var wbase = (hash32('w' + toks[i - 1] + ' ' + t) % NUM_BUCKETS) * DIM;
                for (var d3 = 0; d3 < DIM; d3++) hRaw[d3] += Eb[wbase + d3];
                n++;
            }
        }
        if (n === 0) return false;
        var norm = 0;
        for (var d4 = 0; d4 < DIM; d4++) {
            hRaw[d4] /= n;
            norm += hRaw[d4] * hRaw[d4];
        }
        norm = Math.sqrt(norm) || 1;
        for (var d5 = 0; d5 < DIM; d5++) hNorm[d5] = hRaw[d5] / norm;
        return true;
    }

    // ============================================================
    // Scorers
    // ============================================================
    var logits = new Float32Array(N_INTENTS);

    function softmaxTop(k) {
        var maxL = -Infinity;
        for (var c = 0; c < N_INTENTS; c++) {
            var s = B[c];
            var base = c * DIM;
            for (var d = 0; d < DIM; d++) s += W[base + d] * hRaw[d];
            logits[c] = s;
            if (s > maxL) maxL = s;
        }
        var sum = 0;
        for (var c2 = 0; c2 < N_INTENTS; c2++) {
            logits[c2] = Math.exp(logits[c2] - maxL);
            sum += logits[c2];
        }
        var out = [];
        for (var c3 = 0; c3 < N_INTENTS; c3++) out.push({ idx: c3, p: logits[c3] / sum });
        out.sort(function (a, b) { return b.p - a.p; });
        return out.slice(0, k);
    }

    function centroidTop(k) {
        var out = [];
        for (var c = 0; c < N_INTENTS; c++) {
            var base = c * DIM;
            var s = 0;
            for (var d = 0; d < DIM; d++) s += C[base + d] * hNorm[d];
            out.push({ idx: c, cos: s });
        }
        out.sort(function (a, b) { return b.cos - a.cos; });
        return out.slice(0, k);
    }

    // ============================================================
    // Public API: match(text, topN) -> [{type, target?, intent?, confidence}]
    //
    // Candidates come from the softmax head ONLY — the trained OOS class
    // is what rejects off-topic input. Centroid cosine can boost a
    // candidate's confidence when both scorers agree, but can never
    // create a candidate on its own.
    // ============================================================
    api.match = function (text, topN) {
        if (!api.ready || !text) return [];
        if (!embed(text)) return [];

        var k = Math.max(6, topN || 6);
        var soft = softmaxTop(k);
        var cent = centroidTop(k);
        var cosByIdx = new Map();
        for (var j = 0; j < cent.length; j++) cosByIdx.set(cent[j].idx, cent[j].cos);

        var results = [];
        for (var i = 0; i < soft.length; i++) {
            var idx = soft[i].idx;
            var prob = soft[i].p;
            var meta = INTENTS[idx];
            if (!meta || meta.type === 'oos') continue;
            if (prob < 0.15) continue;
            var cos = cosByIdx.has(idx) ? cosByIdx.get(idx) : -1;
            var conf = (prob >= 0.25 && cos >= 0.6) ? Math.max(prob, cos) : prob;
            var out = { type: meta.type, confidence: conf };
            if (meta.target !== undefined) out.target = meta.target;
            if (meta.intent) out.intent = meta.intent;
            results.push(out);
        }

        results.sort(function (a, b) { return b.confidence - a.confidence; });
        return results.slice(0, topN || 6);
    };

    api.ready = true;
})();
